def solve():
    m = 52
    N_prime = 1960
    best_k = 0

    for M in range(1, N_prime + 1):
        m_prime = min(M, m)
        counts = {}
        for i in range(1, m_prime):
            counts[i] = 2
        counts[m_prime] = abs(M - m) + 1

        # Maximize K(v) = sum_{i*j=v} c_i * c_j
        # The possible values of i and j are in 1...m_prime
        # Let's compute all possible v and their counts.
        k_vals = {}
        for i in range(1, m_prime + 1):
            for j in range(1, m_prime + 1):
                v = i * j
                k_vals[v] = k_vals.get(v, 0) + counts[i] * counts[j]

        current_max_k = max(k_vals.values())
        if current_max_k > best_k:
            best_k = current_max_k
            best_M = M
            best_v = max(k_vals, key=k_vals.get)

    return best_k, best_M, best_v

