def brute_force_1d(N, m):
    M = N - m + 1
    max_k = 0
    for i in range(1 << M):
        s = [(i >> j) & 1 for j in range(M)]
        f = []
        for x in range(1, N + 1):
            current_f = 0
            for j in range(max(1, x - m + 1), min(x, M) + 1):
                current_f += s[j-1]
            f.append(current_f)

        counts = {}
        for val in f:
            if val > 0:
                counts[val] = counts.get(val, 0) + 1
        if counts:
            max_k = max(max_k, max(counts.values()))
    return max_k

