def solve_1d(N, m, v):
    best_k = 0
    for s in range(1, N - m + 2):
        if s + v - 1 > N - m + 1:
            break
        positions = [s + i for i in range(v)]
        count = 0
        for x in range(1, N + 1):
            lower = max(1, x - m + 1)
            upper = min(N - m + 1, x)
            if lower <= upper:
                current_v = 0
                for p in positions:
                    if lower <= p <= upper:
                        current_v += 1
                if current_v == v:
                    count += 1
        best_k = max(best_k, count)
    return best_k

