def solve_1d_brute(N, m):
    max_kx = 0
    for v in range(1, N + 1):
        # For a fixed v, try all possible s and all possible "spreads".
        # But wait, the formula (q+1)m - v + 1 was derived assuming 
        # the positions are s, s+1, ..., s+v-1.
        # Let's just check if that's the best spread.
        # The intersection of I_j is largest when x_j are as close as possible.
        # So x_j = s, s+1, ..., s+v-1 is indeed the best spread for a fixed v.
        # Let's re-calculate best_k for each v.
        best_k_for_v = 0
        for s in range(1, N - m + 2):
            if s + v - 1 > N - m + 1:
                break
            positions = [s + i for i in range(v)]
            count = 0
            for x in range(1, N + 1):
                lower = max(1, x - m + 1)
                upper = min(N - m + 1, x)
                if lower <= upper:
                    current_v = 0
                    for p in positions:
                        if lower <= p <= upper:
                            current_v += 1
                    if current_v == v:
                        count += 1
            best_k_for_v = max(best_k_for_v, count)
        max_kx = max(max_kx, best_k_for_v)
    return max_kx

