def maximize_ad_bc(N, m):
    M = (N - m + 1) * m
    max_val = 0
    # a+b <= N, a+2b <= M
    # c+d <= N, c+2d <= M
    # We can iterate over all a, b, c, d.
    for a in range(N + 1):
        for b in range(N - a + 1):
            if a + 2 * b > M:
                continue
            for c in range(N + 1):
                for d in range(N - c + 1):
                    if c + 2 * d > M:
                        continue
                    max_val = max(max_val, a * d + b * c)
    return max_val

