def solve_1d(N, m):
    import itertools
    max_k = 0
    # The number of tiles can be anything from 0 to N-m+1.
    # But we can assume we use some number of tiles.
    # To make it feasible, let's try a more systematic approach.
    # g(x) = sum_{i \in S} \mathbb{I}_{x \in [i, i+m-1]}
    # g(x) is the number of s \in S such that s \le x \le s+m-1.
    # This is the same as s \in [x-m+1, x].
    # So g(x) is the number of elements in S \cap [x-m+1, x].
    # Let S be a subset of {0, 1, ..., N-m}.
